/// <summary>
/// Constructs a new TMS engine lines temp builder.
/// </summary>
/// <param name = "_shipmentUOM">METShipmentUOM</param>
/// <param name = "_processLinesTmp">Temp table raw data</param>
/// <param name = "_lineTmpSum">Temp table summed by LineCommodity</param>
/// <param name = "_tmsShipmentOrderIdentifier">SO finalisation shipment id</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">Sales order header record</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_ccrHelper">CCR helper class instance</param>
/// <param name = "_isKegItem">SO finalisation shipment id</param>
/// <returns>An instance of <c>METTMSEngineLinesTmpBuilder</c></returns>
public static METTMSShipmentItemGroupTOUOM construct(METShipmentUOM                         _shipmentUOM,
                                                   METTMSEngineTransferOrderProccessLinesTmp _processLinesTmp,
                                                   METTMSEngineTransferOrderProccessLinesTmp _lineTmpSum,
                                                   METTMSShipmentOrderIdentifier          _tmsShipmentOrderIdentifier,
                                                   InventLocationId                       _headerInventLocationId,
                                                   boolean                                _hasCCR,
                                                   boolean                                _isToteCustomer,
                                                   METTMSCCRTableHelper                   _ccrHelper = null,
                                                   boolean                                _isKegItem = false)
{
    METTMSShipmentItemGroupTOUOM result;
    boolean error = false;

    switch (_shipmentUOM)
    {
        case METConstants::unitCSE :
            result = _hasCCR ? new METTMSShipmentItemGroupTOUOM_CSECCR()
                             : new METTMSShipmentItemGroupTOUOM_CSE();
            break;

        case METConstants::unitTOT :
            result = _hasCCR ? new METTMSShipmentItemGroupTOUOM_TOTCCR()
                             : new METTMSShipmentItemGroupTOUOM_TOT();
            break;

        case METConstants::unitPAL :
            result = _hasCCR ? new METTMSShipmentItemGroupTOUOM_PALCCR()
                             : new METTMSShipmentItemGroupTOUOM_PAL();
            break;

        default:
            result = new METTMSShipmentItemGroupTOUOM_Default();
            break;
    }

    if (error)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    result.initParameters(_processLinesTmp, _lineTmpSum, _tmsShipmentOrderIdentifier, _headerInventLocationId, _isToteCustomer, _ccrHelper, _isKegItem);

    return result;
}

/// <summary>
/// Initialise class parameters
/// </summary>
/// <param name = "_processLinesTmp">Temp table raw data</param>
/// <param name = "_lineTmpSum">Temp table summed by LineCommodity</param>
/// <param name = "_tmsShipmentOrderIdentifier">SO finalisation shipment id</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_ccrHelper">CCR helper class instance</param>
/// <param name = "_isKegItem">SO finalisation shipment id</param>
void initParameters(METTMSEngineTransferOrderProccessLinesTmp _processLinesTmp,
                    METTMSEngineTransferOrderProccessLinesTmp _lineTmpSum,
                    METTMSShipmentOrderIdentifier          _tmsShipmentOrderIdentifier,
                    InventLocationId                       _headerInventLocationId,
                    boolean                                _isToteCustomer,
                    METTMSCCRTableHelper                   _ccrHelper = null,
                    boolean                                _isKegItem = false)
{
    processLinesTmp = _processLinesTmp;
    lineTmpSum = _lineTmpSum;
    tmsShipmentOrderIdentifier = _tmsShipmentOrderIdentifier;
    isKegItem = _isKegItem;
    isToteCustomer = _isToteCustomer;

    inventParameters = InventParameters::find();

    // calculate the sums for RepackContainersByCommodity
    this.initSumRepackContainersByCommodity(_processLinesTmp, lineTmpSum.LineCommodity);

    // Pallet volume & weight use SO's main warehouse
    METInventLocation metInventLocation = METInventLocation::findByInventLocationId(_headerInventLocationId);
    whsPalletVolume = METInventLocation.WHSPalletVolume;
    whsPalletWeight = METInventLocation.WHSPalletWeight;

    headerInventLocationId = _headerInventLocationId;

    ccrHelper = _ccrHelper;
}

/// <summary>
/// Init CCR parameters, only called from METTMSShipmentItemGroupUOM_*CCR\initParameters
/// </summary>
void initCCRParameters()
{
    this.initSumRepackContainersByCommodityCCR(lineTmpSum.LineCommodity);
}

/// <summary>
/// Calculates the sum for RepackContainersByCommodity when WH are different in temp table (CSD, xDock)
/// </summary>
/// <param name = "_processLinesTmp">Temp table raw data</param>
/// <param name = "_commodity">Current commodity being processed by METTMSShipmentItemGroupHelper</param>
protected void initSumRepackContainersByCommodity(METTMSEngineTransferOrderProccessLinesTmp _processLinesTmp, METTMSCommodity _commodity)
{
    METWHSPalletVolume  whsToteVolume;
    METWHSPalletVolume  whsCaseVolume;
    METWHSPalletWeight  whsToteWeight;
    int repackContainersByCommodity;
    METTMSEngineTransferOrderProccessLinesTmp  processLinesGroupByWh;

    processLinesGroupByWh.linkPhysicalTableInstance(_processLinesTmp);

    // Sum RepackCountSecurity and RepackCountSecurity by commodity and supplying warehouse
    // could have multiple supplying WH for the same commodity
    while select sum(RepackCountSecurity), sum(RepackCountNonSecurity)
            from processLinesGroupByWh
        group by LineCommodity, Line_SupplyWhs
           where processLinesGroupByWh.LineCommodity == _commodity
    {  
        repackContainersByCommodity = real2int(roundUp(processLinesGroupByWh.RepackCountSecurity, 1) + roundUp(processLinesGroupByWh.RepackCountNonSecurity, 1));

        [whsCaseVolume, whsToteVolume, whsToteWeight] = this.getContainerTypeParameters(processLinesGroupByWh.Line_SupplyWhs);

        // sum qty
        sumRepackContainersByCommodityQty += repackContainersByCommodity;

        // sum volume
        sumRepackContainersByCommodityCaseVolume += repackContainersByCommodity * whsCaseVolume;
        sumRepackContainersByCommodityToteVolume += repackContainersByCommodity * whsToteVolume;

        // sum weight
        sumRepackContainersByCommodityToteWeight += repackContainersByCommodity * whsToteWeight;
    }
}

/// <summary>
/// Get container type parameters for cardboard and plastic
/// </summary>
/// <param name = "_inventLocationId">Warehouse</param>
/// <returns>Container with case/tote volume and tote weight</returns>
protected container getContainerTypeParameters(InventLocationId _inventLocationId)
{
    METContainerTypeTable containerTypeTable;
    METWHSPalletVolume    whsCaseVolume;
    METWHSPalletVolume    whsToteVolume;
    METWHSPalletWeight    whsToteWeight;

    containerTypeTable   = METContainerTypeTable::find(inventParameters.METCardboardContainerID, _inventLocationId);
    whsCaseVolume   = containerTypeTable.ContainerVolume;

    containerTypeTable   = METContainerTypeTable::find(inventParameters.METPlasticContainerID, _inventLocationId);
    whsToteVolume   = containerTypeTable.ContainerVolume;
    whsToteWeight   = containerTypeTable.Weight;

    return [whsCaseVolume, whsToteVolume, whsToteWeight];
}

/// <summary>
/// Abstract method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
abstract METWHSPalletVolume cube(METQty _quantity)
{

}

/// <summary>
/// Abstract method to calculate TSIG quantity
/// </summary>
/// <returns>TSIG quantity</returns>
abstract METQty quantity()
{

}

/// <summary>
/// Abstract method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
abstract METWHSPalletWeight weight(METQty _quantity)
{

}

/// <summary>
/// Abstract method for the TSIG quantity UOM
/// </summary>
/// <returns>Shipment UOM e.g. CSE, PAL...</returns>
abstract METShipmentUOM shipmentUOM()
{

}

/// <summary>
/// Creates a single TSIG record
/// Was previously defined in class\METTMSEngineSalesOrderProccess\createTMSShipmentItemGroup
/// </summary>
/// <returns>The created <c>METTMSShipmentItemGroup</c> record</returns>
public METTMSShipmentItemGroup createRecord()
{
    METTMSShipmentItemGroup     tmsShipmentItemGroup;

    tmsShipmentItemGroup.clear();
    tmsShipmentItemGroup.initValue();
    tmsShipmentItemGroup.TMSShipmentOrderIdentifier = tmsShipmentOrderIdentifier;
    tmsShipmentItemGroup.QuantityUOM = this.shipmentUOM();
    tmsShipmentItemGroup.Commodity  = lineTmpSum.LineCommodity;

    this.calcOrder(tmsShipmentItemGroup);

    tmsShipmentItemGroup.IsRatingUnit = this.isRatingUnit(tmsShipmentItemGroup.QuantityUOM);
    tmsShipmentItemGroup.insert();

    return tmsShipmentItemGroup;
}

/// <summary>
/// Defines default order _tmsShipmentItemGroup fields are calculated first Quantity, second Weight and third Cube
/// </summary>
/// <param name = "_tmsShipmentItemGroup"><c>METTMSShipmentItemGroup</c> to initialise fields</param>
void calcOrder(METTMSShipmentItemGroup _tmsShipmentItemGroup)
{        
    _tmsShipmentItemGroup.Quantity = this.quantity();
    _tmsShipmentItemGroup.Weight = this.weight(_tmsShipmentItemGroup.Quantity);
    _tmsShipmentItemGroup.Cube = this.cube(_tmsShipmentItemGroup.Quantity);
}

/// <summary>
/// return Rating unit
/// </summary>
/// <param name = "_shipmentUOM">METShipmentUOM</param>
/// <returns>boolean <c>boolean</c></returns>
private boolean isRatingUnit(METShipmentUOM _shipmentUOM)
{
    return METTMSShipmentRatingUnit::find(headerInventLocationId, _shipmentUOM).RecId;
}

/// <summary>
/// Method to calc the Count of (Unique CCR “Tote ID”s) for all the CCR records for the Sales order
/// </summary>
/// <param name = "_commodity">TMS commodity</param>
protected void initSumRepackContainersByCommodityCCR(METTMSCommodity _commodity)
{       
    int sumRepackContainersByCommodityQtyTOBCCR, sumRepackContainersByCommodityQtyNotTOBCCR; // Not used for TSIG

    [sumRepackContainersByCommodityQtyCCR, 
     sumRepackContainersByCommodityQtyTOBCCR,
     sumRepackContainersByCommodityQtyNotTOBCCR,
     sumRepackContainersByCommodityCaseVolumeCCR,
     sumRepackContainersByCommodityToteVolumeCCR,
     sumRepackContainersByCommodityToteWeightCCR] = ccrHelper.getCommodityResults(_commodity);
}
